style.css:
@namespace url(http://www.w3.org/1999/xhtml);

/* 替换逻辑：
   1. unicode-range: U+2E80-FFFF 覆盖了绝大部分中文字符、符号。
   2. unicode-range: U+0000-2E7F 覆盖了英文、数字及常用西文标点。
   3. src: local('字体名') 直接调用本地系统已安装的字体。
*/

/* 宋体 / SimSun */
@font-face {
    font-family: 'SimSun';
    unicode-range: U+2E80-FFFF;
    src: local('Noto Sans SC');
}
@font-face {
    font-family: 'SimSun';
    unicode-range: U+0000-2E7F;
    src: local('Aptos');
}

/* 新宋体 / NSimSun */
@font-face {
